contract InvMutTest {
    C c;

    constructor() { c = new C(); }
    function __ESBMC_reverted() internal returns (bool) {}
    function __ESBMC_assume(bool) internal pure {}
    receive() external payable {}

    function run(uint v1, uint v2) public {
        c.SetMinSum(v1); if (__ESBMC_reverted()) return;
        uint afterFirst = c.MinSum(); if (__ESBMC_reverted()) return;

        bool reverted;
        c.SetMinSum(v2); bool __rev0 = __ESBMC_reverted(); if (__rev0) {
            reverted = true;
        } else {
            reverted = false;
        }

        uint afterSecond = c.MinSum(); if (__ESBMC_reverted()) return;

        assert(afterFirst == v1 && (reverted ? afterSecond == v1 : afterSecond == v2));
    }
}

